import { createDrawer, type Drawer as DrawerController, type DrawerSide } from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, createUniqueId, merge, omit, useContext } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface DrawerProps {
  /** Controlled: the host owns the open state and this is the only thing that changes it. */
  readonly open?: boolean;
  /** Open at mount; ignored while `open` is set. */
  readonly defaultOpen?: boolean;
  /** A request to change the open state: uncontrolled it is accepted, controlled the host may ignore it. */
  readonly onOpenChange?: (open: boolean) => void;
  /** The edge the panel is anchored to: a side rail, or the bottom sheet. @default "right" */
  readonly side?: DrawerSide;
  /** `aria-modal`, the Tab trap, the scroll lock and the backdrop (default `true`). */
  readonly modal?: boolean;
  /** A backdrop click or an outside press closes it (default `true`). */
  readonly dismissable?: boolean;
  readonly id?: string;
  /** The element the layer is portalled into (default `document.body`), for a host with its own overlay root. */
  readonly mount?: Element;
  readonly children?: JSX.Element;
}

export interface DrawerTriggerProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerHeaderProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerTitleProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerBodyProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerFooterProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DrawerCloseProps {
  /** The accessible name of the icon button (default `"Close"`). */
  readonly label?: string;
  readonly class?: string;
  readonly children?: JSX.Element;
}

const DrawerContext = createContext<{
  readonly drawer: DrawerController;
  /** The title's id: the primitive puts it on `aria-labelledby`, so the panel is named by its heading. */
  readonly titleId: string;
  readonly mount: () => Element | undefined;
}>();

// One positioned layer for the backdrop and the panel, out of the page's flow and over everything but a toast. It never takes
// the page's pointer itself: the panel turns that back on, and so does the backdrop when the drawer is modal.
const layerClass = css.cn(
  css.position("fixed"),
  css.inset("0"),
  // `z-index` takes an `<integer>`, which a `number` token is not: the class reads the token by hand, as the dialog's layer
  css.zIndex("var(--z-dialog)"),
  css.pointerEvents("none"),
);

const backdropClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.bg(t.color.scrim),
  css.pointerEvents("auto"),
);

// The panel is edge-anchored: a rail on the left or the right, or a sheet across the bottom. It stays in the DOM while closed
// and hides with `visibility` rather than the `hidden` attribute, so the slide can play both ways and the primitive can move
// the focus into it before the first open frame (a `display: none` panel cannot take the focus).
const panel = css.cv({
  base: css.cn(
    css.position("absolute"),
    css.display("flex"),
    css.flexDirection("column"),
    css.margin("0"),
    css.overflow("hidden"),
    css.pointerEvents("auto"),
    css.color(t.color.text),
    css.boxShadow(t.shadow.popover),
    // the panel takes the focus itself (`tabindex="-1"`) when it holds nothing focusable: a ring around the whole panel is noise
    css.outline("none"),
  ),
  variants: {
    side: {
      left: css.cn(
        css.top("0"),
        css.bottom("0"),
        css.left("0"),
        css.width("min(22rem, 100vw)"),
        css.maxWidth("100%"),
        css.bg(t.color.overlayBackground),
        css.borderInlineEnd("1px solid", t.color.overlayBorder),
      ),
      right: css.cn(
        css.top("0"),
        css.bottom("0"),
        css.right("0"),
        css.width("min(22rem, 100vw)"),
        css.maxWidth("100%"),
        css.bg(t.color.overlayBackground),
        css.borderInlineStart("1px solid", t.color.overlayBorder),
      ),
      // the sheet: full width, its top corners rounded and its own surface token, and a height the body scrolls inside
      bottom: css.cn(
        css.left("0"),
        css.right("0"),
        css.bottom("0"),
        css.width("100%"),
        css.maxHeight("85dvh"),
        css.bg(t.color.sheetBackground),
        css.borderTop("1px solid", t.color.overlayBorder),
        css.borderStartStartRadius(t.radius.xl),
        css.borderStartEndRadius(t.radius.xl),
      ),
    },
  },
  defaultVariants: { side: "right" },
});

// The slide reads one state off `data-state` (`right-open`, `bottom-closed`, ...), so exactly one rule matches and no two
// declarations of the same property compete: closed it is off screen and invisible, open it is in place. With reduced motion
// there is no transition, so `visibility` flips at once instead of waiting for a slide that does not happen.
const panelMotion = css.cn(
  css.visibility("hidden"),
  css.attr("data-state", "left-closed")(css.transform("translateX(-100%)")),
  css.attr("data-state", "right-closed")(css.transform("translateX(100%)")),
  css.attr("data-state", "bottom-closed")(css.transform("translateY(100%)")),
  css.attr("data-state", "left-open")(css.visibility("visible"), css.transform("none")),
  css.attr("data-state", "right-open")(css.visibility("visible"), css.transform("none")),
  css.attr("data-state", "bottom-open")(css.visibility("visible"), css.transform("none")),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.cn(
      css.transition("transform 200ms ease-out, visibility 0s"),
      css.attr(
        "data-state",
        "left-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
      css.attr(
        "data-state",
        "right-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
      css.attr(
        "data-state",
        "bottom-closed",
      )(css.transition("transform 200ms ease-out, visibility 0s linear 200ms")),
    ),
  ),
);

const headerClass = css.cn(
  css.display("flex"),
  css.alignItems("start"),
  css.justifyContent("space-between"),
  css.gap(t.space._3),
  css.padding(t.space._4),
  css.borderBottom("1px solid", t.color.overlayBorder),
  css.flex("none"),
);

const titleClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.sizeLg),
  css.fontWeight("600"),
  css.color(t.color.text),
);

const closeClass = css.cn(
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._6),
  css.height(t.space._6),
  css.margin("0"),
  css.padding("0"),
  css.border("none"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.color(t.color.muted),
  css.fontSize(t.font.sizeLg),
  css.lineHeight(1),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground), css.color(t.color.text)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const bodyClass = css.cn(
  css.flex("1 1 auto"),
  css.overflowY("auto"),
  css.overscrollBehavior("contain"),
  css.padding(t.space._4),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

const footerClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("end"),
  css.gap(t.space._2),
  css.padding(t.space._4),
  css.borderTop("1px solid", t.color.overlayBorder),
  css.flex("none"),
);

/**
 * A drawer or bottom sheet, styled: `Drawer.Trigger` opens a panel on the edge of the viewport. `createDrawer` owns the open
 * state (controlled by `open`), the ARIA, the focus into the panel and back to whatever opened it, the Tab cycle, Escape, the
 * backdrop, the outside press and the page's scroll lock; the kit adds the three edges, the slide, the surface and the slots.
 *
 * The panel is named by `DrawerTitle` (`aria-labelledby`) and closes from a `DrawerClose` in its header, the backdrop, Escape
 * or the trigger. `side` and `modal` are the whole presentation switch: `{ side: "bottom" }` is the sheet, a rail is
 * `{ side: "right" }`, and a non-modal rail (`modal={false}`) keeps the page's scroll, focus and clicks.
 */
export const Drawer = (props: DrawerProps): JSX.Element => {
  // the heading names the panel: the id is made here, because `createDrawer` needs it at creation time
  const titleId = createUniqueId();
  const drawer = createDrawer({
    id: props.id,
    get open() {
      return props.open;
    },
    defaultOpen: props.defaultOpen,
    get side() {
      return props.side;
    },
    get modal() {
      return props.modal;
    },
    get dismissable() {
      return props.dismissable;
    },
    labelledby: titleId,
    get onOpenChange() {
      return props.onOpenChange;
    },
  });
  const mount = () => props.mount;
  return <DrawerContext value={{ drawer, titleId, mount }}>{props.children}</DrawerContext>;
};

/** The button that opens the drawer: `Button` unless `render` says otherwise. It is the element with `aria-haspopup`. */
export const DrawerTrigger = (props: DrawerTriggerProps): JSX.Element => {
  const { drawer } = useContext(DrawerContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button` by default, and the button owns the attribute, as `Dialog` does
  const merged = merge(rest, drawer.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The panel and the wash under it, portalled into `document.body` (or `mount`) so an ancestor's `transform`, `filter`,
 * `contain` or `overflow` can neither clip the layer nor become the containing block of its `position: fixed`.
 */
export const DrawerContent = (props: DrawerContentProps): JSX.Element => {
  const { drawer, mount } = useContext(DrawerContext);
  const merged = merge(omit(props, "render", "class", "children"), drawer.contentProps, () => ({
    "data-part": "drawer",
    get "data-side"() {
      return drawer.side();
    },
    get "data-state"() {
      return `${drawer.side()}-${drawer.open() ? "open" : "closed"}`;
    },
    // the panel hides with `visibility` (panelMotion), not with `hidden`: the primitive's attribute would cut the slide and
    // make the panel unfocusable at the moment the focus moves into it
    hidden: false,
    get class() {
      return css.cn(panel({ side: drawer.side() }), panelMotion, props.class);
    },
  }));
  return (
    <Portal mount={mount()}>
      <div data-part="drawer-layer" class={layerClass}>
        <div {...drawer.backdropProps} data-part="drawer-backdrop" class={backdropClass} />
        {renderPart(props, merged, undefined, (part) => (
          <div {...part}>{props.children}</div>
        ))}
      </div>
    </Portal>
  );
};

/** The top of the panel: the title and the close button. */
export const DrawerHeader = (props: DrawerHeaderProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-header",
      get class() {
        return css.cn(headerClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The panel's visible heading, and the name the primitive points `aria-labelledby` at. */
export const DrawerTitle = (props: DrawerTitleProps): JSX.Element => {
  const { titleId } = useContext(DrawerContext);
  return renderPart(
    props,
    {
      id: titleId,
      "data-part": "drawer-title",
      get class() {
        return css.cn(titleClass, props.class);
      },
    },
    undefined,
    (part) => <h2 {...part}>{props.children}</h2>,
  );
};

/** The panel's body: the only part that scrolls when the content is taller than the edges allow. */
export const DrawerBody = (props: DrawerBodyProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-body",
      get class() {
        return css.cn(bodyClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The panel's footer: actions, against the bottom edge. */
export const DrawerFooter = (props: DrawerFooterProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "drawer-footer",
      get class() {
        return css.cn(footerClass, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The close control in the header: a small icon button with an accessible name. */
export const DrawerClose = (props: DrawerCloseProps): JSX.Element => {
  const { drawer } = useContext(DrawerContext);
  return (
    <button
      type="button"
      data-part="drawer-close"
      class={css.cn(closeClass, props.class)}
      aria-label={props.label ?? "Close"}
      onClick={() => {
        // the trigger's handler toggles, which is a close while the drawer is open
        if (drawer.open()) {
          drawer.triggerProps.onClick();
        }
      }}
    >
      {props.children ?? <span aria-hidden="true">×</span>}
    </button>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import { createSignal } from "solid-js";

import { Button } from "./button.tsx";
import { Input } from "./input.tsx";
import {
  Drawer,
  DrawerBody,
  DrawerClose,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "./drawer.tsx";

/** What a mounted demo hands the test: where it lives, what the controlled host saw, and a teardown. */
export interface MountedDrawer {
  readonly root: HTMLElement;
  /** Every open state the controlled drawer's host was asked for, in order. */
  readonly requests: ReadonlyArray<boolean>;
  /** The controlled host stops accepting requests: the next close is refused. */
  readonly hold: () => void;
  readonly dispose: () => void;
}

/**
 * Mounts the styled drawer in ordinary use: a controlled right-hand rail with a small form (and a `Cancel` in its footer),
 * and an uncontrolled bottom sheet. The trigger opens each; the primitive owns the rest. The host can `hold()` to show a
 * controlled drawer refusing to close.
 */
export const mountDrawer = (): MountedDrawer => {
  const root = document.createElement("div");
  document.body.append(root);
  const requests: boolean[] = [];
  let accept = true;
  const [filters, setFilters] = createSignal(false);

  const dispose = render(
    () => (
      <div>
        <Drawer
          open={filters()}
          onOpenChange={(open) => {
            requests.push(open);
            if (accept) {
              setFilters(open);
            }
          }}
        >
          <DrawerTrigger>Filters</DrawerTrigger>
          <DrawerContent>
            <DrawerHeader>
              <DrawerTitle>Filters</DrawerTitle>
              <DrawerClose />
            </DrawerHeader>
            <DrawerBody>
              <Input aria-label="Search" placeholder="Search the report" />
            </DrawerBody>
            <DrawerFooter>
              <Button tone="quiet" onClick={() => setFilters(false)}>
                Cancel
              </Button>
              <Button tone="accent" onClick={() => setFilters(false)}>
                Apply
              </Button>
            </DrawerFooter>
          </DrawerContent>
        </Drawer>
        <Drawer side="bottom">
          <DrawerTrigger>Open the sheet</DrawerTrigger>
          <DrawerContent>
            <DrawerHeader>
              <DrawerTitle>Share</DrawerTitle>
              <DrawerClose />
            </DrawerHeader>
            <DrawerBody>A bottom sheet for the action that belongs to the whole page.</DrawerBody>
            <DrawerFooter>
              <Button tone="accent">Copy link</Button>
            </DrawerFooter>
          </DrawerContent>
        </Drawer>
      </div>
    ),
    root,
  );

  return {
    root,
    requests,
    hold: () => {
      accept = false;
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedDrawer, mountDrawer } from "./drawer.fixture";

/** Solid 2 delivers events through its delegated listener on a later turn. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

/** The slide is 200 ms: the geometry is final only after it, as a reader sees it. */
const settleSlide = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 260));

const live: MountedDrawer[] = [];

const mounted = (): MountedDrawer => {
  const instance = mountDrawer();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends HTMLElement>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`drawer: no ${selector}`);
  }
  return element;
};

/** The trigger of a drawer, by its label: the fixture has one per drawer. */
const trigger = (root: HTMLElement, label: string): HTMLButtonElement => {
  const found = [...root.querySelectorAll<HTMLButtonElement>('[aria-haspopup="dialog"]')].find(
    (element) => element.textContent?.trim() === label,
  );
  if (found === undefined) {
    throw new Error(`drawer: no trigger "${label}"`);
  }
  return found;
};

/** A panel by the text of its title: both drawers are in the DOM, closed ones included. */
const panel = (title: string): HTMLElement => {
  const found = [...document.querySelectorAll<HTMLElement>('[data-part="drawer"]')].find(
    (element) => element.querySelector('[data-part="drawer-title"]')?.textContent === title,
  );
  if (found === undefined) {
    throw new Error(`drawer: no panel "${title}"`);
  }
  return found;
};

const inside = (root: HTMLElement, name: string): HTMLElement =>
  required(root, `[data-part="${name}"]`);

const click = async (element: HTMLElement): Promise<void> => {
  element.click();
  await settle();
};

/** A key on whatever holds the focus, as a reader's would arrive. */
const press = async (key: string, init: KeyboardEventInit = {}): Promise<void> => {
  const target =
    document.activeElement instanceof HTMLElement ? document.activeElement : document.body;
  target.dispatchEvent(
    new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init }),
  );
  await settle();
};

const background = (token: string): string => {
  const probe = document.createElement("div");
  probe.style.backgroundColor = `var(${token})`;
  document.body.append(probe);
  const value = getComputedStyle(probe).backgroundColor;
  probe.remove();
  return value;
};

describe("Drawer", () => {
  it("opens from its trigger as a modal dialog", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    const dialog = panel("Filters");

    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(open.getAttribute("aria-controls")).toBe(dialog.id);
    expect(dialog.getAttribute("role")).toBe("dialog");
    expect(dialog.getAttribute("aria-modal")).toBeNull();
    // a closed rail is off screen and out of the accessibility tree, not in the page's flow
    expect(getComputedStyle(dialog).visibility).toBe("hidden");

    open.focus();
    await click(open);

    expect(open.getAttribute("aria-expanded")).toBe("true");
    expect(dialog.getAttribute("aria-modal")).toBe("true");
    expect(dialog.getAttribute("data-state")).toBe("right-open");
    expect(getComputedStyle(dialog).visibility).toBe("visible");
    // portalled out of the fixture, into the body, so no ancestor can clip it or hold its `position: fixed`
    expect(root.contains(dialog)).toBe(false);
    expect(dialog.closest('[data-part="drawer-layer"]')?.parentElement).toBe(document.body);
  });

  it("names the panel by its title", async () => {
    const { root } = mounted();
    await click(trigger(root, "Filters"));
    const dialog = panel("Filters");
    const title = inside(dialog, "drawer-title");

    expect(dialog.getAttribute("aria-labelledby")).toBe(title.id);
    expect(title.textContent).toBe("Filters");
    // the close control is an icon button with an accessible name
    expect(inside(dialog, "drawer-close").getAttribute("aria-label")).toBe("Close");
  });

  it("moves the focus into the panel, keeps Tab inside, and returns it on Escape", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    open.focus();
    await click(open);
    const dialog = panel("Filters");
    const close = inside(dialog, "drawer-close");
    const footerButtons = [
      ...inside(dialog, "drawer-footer").querySelectorAll<HTMLButtonElement>("button"),
    ];
    const last = footerButtons[footerButtons.length - 1];
    if (last === undefined) {
      throw new Error("drawer: no footer button");
    }

    expect(document.activeElement).toBe(close);

    last.focus();
    await press("Tab");
    expect(document.activeElement).toBe(close);

    close.focus();
    await press("Tab", { shiftKey: true });
    expect(document.activeElement).toBe(last);

    await press("Escape");
    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(dialog.getAttribute("aria-modal")).toBeNull();
    expect(document.activeElement).toBe(open);
  });

  it("closes on a press on the backdrop", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    open.focus();
    await click(open);
    const backdrop = required<HTMLElement>(document, '[data-part="drawer-backdrop"]');

    expect(backdrop.hidden).toBe(false);
    backdrop.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, cancelable: true }));
    await settle();

    expect(open.getAttribute("aria-expanded")).toBe("false");
    expect(document.activeElement).toBe(open);
  });

  it("locks the page's scroll while open and releases it on close", async () => {
    const { root } = mounted();
    const open = trigger(root, "Filters");
    expect(document.documentElement.style.overflow).toBe("");

    await click(open);
    expect(document.documentElement.style.overflow).toBe("hidden");

    await press("Escape");
    expect(document.documentElement.style.overflow).toBe("");
  });

  it("renders the bottom variant as a full-width sheet on its own surface", async () => {
    const { root } = mounted();
    await click(trigger(root, "Open the sheet"));
    await settleSlide();
    const sheet = panel("Share");
    const style = getComputedStyle(sheet);
    const rect = sheet.getBoundingClientRect();

    // the top corners are the theme's radius, the bottom ones meet the viewport edge
    expect(style.borderTopLeftRadius).not.toBe("0px");
    expect(style.borderTopRightRadius).not.toBe("0px");
    expect(style.borderBottomLeftRadius).toBe("0px");
    expect(Math.round(rect.left)).toBe(0);
    expect(Math.round(rect.width)).toBe(window.innerWidth);
    expect(Math.round(rect.bottom)).toBe(window.innerHeight);
    expect(style.maxHeight).not.toBe("none");
    // the sheet's surface is a token of its own, not the rail's
    expect(style.backgroundColor).toBe(background("--color-sheet-background"));
  });

  it("lets a controlled host refuse to close", async () => {
    const instance = mounted();
    const open = trigger(instance.root, "Filters");
    await click(open);
    expect(open.getAttribute("aria-expanded")).toBe("true");

    instance.hold();
    await press("Escape");

    expect(instance.requests.at(-1)).toBe(false);
    expect(open.getAttribute("aria-expanded")).toBe("true");
    expect(panel("Filters").getAttribute("aria-modal")).toBe("true");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
